<style>
:root{--b:#174679;--b2:#0b2a4d;--b3:#2b6cb0;--y:#f6c90e;--bg:#f4f7fc;--l:#e1e8f2;--ink:#0b1b2e;--mute:#5a6f88;--ok:#12703a;--okbg:#e6f6ec;--bad:#b3261e;--badbg:#fdeceb;--warn:#8a4b00;--warnbg:#fff6e0;--r:18px}
*{box-sizing:border-box}
body{margin:0;background:linear-gradient(180deg,#eaf1fb 0,var(--bg) 320px);color:var(--ink);font:15px/1.6 "Segoe UI",system-ui,-apple-system,Roboto,Arial,sans-serif;-webkit-font-smoothing:antialiased}
.w{max-width:1160px;margin:0 auto;padding:0 20px}
button,input{font:inherit}
a{color:inherit}
:focus-visible{outline:3px solid var(--b3);outline-offset:2px;border-radius:8px}
[hidden]{display:none!important}
/* header */
.top{background:radial-gradient(700px 300px at 90% -20%,#2f74bd66,transparent 60%),linear-gradient(165deg,var(--b2),var(--b));color:#fff;padding:22px 0 84px;position:relative;overflow:hidden}
.top:before{content:"";position:absolute;inset:0;background-image:linear-gradient(#ffffff0d 1px,transparent 1px),linear-gradient(90deg,#ffffff0d 1px,transparent 1px);background-size:40px 40px;-webkit-mask:linear-gradient(#000,transparent 90%);mask:linear-gradient(#000,transparent 90%)}
/* meteor */
.meteors{position:absolute;inset:0;overflow:hidden;pointer-events:none;z-index:0}
.meteors i{position:absolute;top:-110px;width:1.5px;border-radius:2px;background:linear-gradient(to bottom,transparent,rgba(255,255,255,.55));opacity:0;transform:translate3d(0,0,0) rotate(35deg);animation:meteor linear infinite;will-change:transform,opacity}
.meteors i:after{content:"";position:absolute;left:50%;bottom:0;width:3px;height:3px;margin-left:-1.5px;border-radius:50%;background:rgba(255,255,255,.7);box-shadow:0 0 6px 1px rgba(255,255,255,.35)}
@keyframes meteor{0%{transform:translate3d(0,0,0) rotate(35deg);opacity:0}10%{opacity:var(--o,.6)}70%{opacity:var(--o,.6)}100%{transform:translate3d(-290px,415px,0) rotate(35deg);opacity:0}}
@media(prefers-reduced-motion:reduce){.meteors{display:none}}
.tb{position:relative;display:flex;align-items:center;gap:14px;flex-wrap:wrap}
.brand{color:#fff;text-decoration:none;display:inline-flex;align-items:center;gap:12px}
.brand i{width:46px;height:46px;border-radius:12px;background:#fff;display:grid;place-items:center;padding:5px;flex:none;box-shadow:0 4px 12px #00000026;overflow:hidden}
.brand i svg{width:36px;height:36px;display:block;flex:none}
.brand b{font-size:17px;font-weight:800;letter-spacing:.8px;display:block;line-height:1.1}
.brand small{font-size:12px;color:#bcd3ee}
.hd{position:relative;margin-top:18px;display:flex;align-items:center;gap:16px;flex-wrap:wrap}
.hd div{flex:1;min-width:240px}
.hd h1{margin:0;font-size:clamp(24px,3.2vw,30px);letter-spacing:-.4px;font-weight:800}
.hd p{margin:4px 0 0;color:#cfe0f5;font-size:14.5px}
.role{display:inline-flex;align-items:center;gap:6px;font-size:11.5px;font-weight:800;letter-spacing:.5px;text-transform:uppercase;padding:6px 12px;border-radius:99px;background:#ffffff1f;color:#fff;border:1px solid #ffffff40}
/* tombol */
.btn{border:1px solid #ffffff4d;background:#ffffff1a;color:#fff;border-radius:11px;padding:9px 15px;font-size:13.5px;font-weight:700;cursor:pointer;text-decoration:none;display:inline-flex;align-items:center;gap:7px;transition:background .15s,transform .15s,border-color .15s}
.btn:active{transform:scale(.98)}
.btn.dk{background:var(--b);color:#fff;border-color:var(--b)}
.btn.dk:hover{background:var(--b2)}
.btn.sm{padding:9px 14px;color:var(--b);background:#fff;border:1.5px solid var(--l)}
.btn.sm:hover{border-color:var(--b3);background:#f5f9ff}
/* kartu */
.card{background:#fff;border:1px solid var(--l);border-radius:var(--r);box-shadow:0 10px 26px rgba(11,42,77,.07);padding:22px;margin-bottom:22px}
.card h2{margin:0 0 4px;font-size:16px}
.card p{margin:0;color:var(--mute);font-size:14px}
.lookup{margin-top:-52px;position:relative;z-index:2;padding:20px}
.lk-head{display:flex;align-items:flex-start;justify-content:space-between;gap:12px;margin-bottom:14px}
.lk-head p{margin:2px 0 0}
.lk-cnt{font-size:12px;font-weight:800;color:var(--mute);background:#f0f4f9;border-radius:99px;padding:4px 10px;font-variant-numeric:tabular-nums;white-space:nowrap;transition:.2s}
.lk-cnt.full{background:var(--okbg);color:var(--ok)}
.lk-form{display:flex;gap:10px;flex-wrap:wrap}
.nrp-in{flex:1;min-width:220px;display:flex;align-items:center;gap:10px;border:1.5px solid var(--l);border-radius:14px;padding:0 14px;background:#fff;transition:border-color .15s,box-shadow .15s;cursor:text}
.nrp-in:hover{border-color:#b5cbe6}
.nrp-in:focus-within{border-color:var(--b3);box-shadow:0 0 0 4px rgba(43,108,176,.15)}
.nrp-in svg{width:20px;height:20px;stroke:var(--mute);fill:none;stroke-width:2;stroke-linecap:round;stroke-linejoin:round;flex:none}
.nrp-in input{flex:1;min-width:0;border:0;outline:0;background:transparent;padding:13px 0;font-size:17px;letter-spacing:1.2px;font-variant-numeric:tabular-nums;color:var(--ink)}
.nrp-in input::placeholder{letter-spacing:0;font-size:15px;color:#9aa9bb}
.lk-form .btn{padding:13px 20px;font-size:14.5px;border-radius:14px}
.lk-form .btn svg{width:16px;height:16px;stroke:currentColor;fill:none;stroke-width:2.2;stroke-linecap:round;stroke-linejoin:round;transition:transform .2s}
.lk-form .btn:hover svg{transform:translateX(3px)}
.err{color:var(--bad);font-size:13px;font-weight:600;margin:8px 0 0;min-height:18px}
/* identitas */
.idcard{margin:-52px 0 20px;position:relative;z-index:2;background:#fff;border:1px solid var(--l);border-radius:20px;box-shadow:0 14px 30px rgba(11,42,77,.1);padding:18px 20px;display:flex;align-items:center;gap:16px;flex-wrap:wrap}
.av{width:52px;height:52px;border-radius:16px;font-size:17px;background:linear-gradient(150deg,var(--b),var(--b3));color:#fff;box-shadow:0 8px 16px rgba(23,70,121,.25);display:grid;place-items:center;font-weight:800;flex:none}
.idinfo{flex:1;min-width:200px}
.idinfo b{display:block;font-size:22px;font-weight:800;letter-spacing:-.3px;line-height:1.2}
.idinfo small{display:block;color:var(--mute);font-size:13px;margin-top:2px}
.idinfo .nrp{display:inline-block;margin-top:4px;background:#eef4fb;color:var(--b);font-weight:700;font-size:12.5px;padding:2px 9px;border-radius:99px;font-variant-numeric:tabular-nums}
/* target kelulusan */
.goal{background:#fff;border:1px solid var(--l);border-radius:18px;box-shadow:0 4px 12px rgba(11,42,77,.05);padding:18px 20px;margin-bottom:12px}
.goal .gt{display:flex;align-items:baseline;justify-content:space-between;gap:10px;flex-wrap:wrap}
.goal .gt span{font-size:12px;font-weight:700;color:var(--mute);text-transform:uppercase;letter-spacing:.5px}
.goal .gt b{font-size:26px;font-weight:800;color:var(--b);font-variant-numeric:tabular-nums}
.goal .gt b small{font-size:14px;color:var(--mute);font-weight:700}
.pbar{height:10px;border-radius:99px;background:#eaf0f8;overflow:hidden;margin:10px 0 0}
.pbar i{display:block;height:100%;border-radius:99px;background:linear-gradient(90deg,var(--b),var(--b3))}
.pbar.done i{background:linear-gradient(90deg,var(--ok),#2fb36a)}
.alert{display:flex;gap:12px;align-items:flex-start;border-radius:14px;padding:14px 16px;font-size:14px;margin:12px 0 0;line-height:1.55}
.alert b{display:block;margin-bottom:2px;font-size:14.5px}
.alert svg{width:20px;height:20px;flex:none;stroke:currentColor;fill:none;stroke-width:2;stroke-linecap:round;stroke-linejoin:round;margin-top:2px}
.alert.ok{background:var(--okbg);color:var(--ok);border:1px solid #bfe5cd}
.alert.rev{background:var(--warnbg);color:var(--warn);border:1px solid #f0dc8a}
.alert.tol{background:var(--badbg);color:var(--bad);border:1px solid #f3c6c2}
.alert.run{background:#eef4fb;color:var(--b);border:1px solid #d0e1f7}
/* ringkasan */
.stats{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin-bottom:22px}
.st{background:#fff;border:1px solid var(--l);border-radius:16px;padding:16px 18px;display:flex;align-items:center;gap:14px;box-shadow:0 4px 12px rgba(11,42,77,.05)}
.st .ic{width:44px;height:44px;border-radius:13px;display:grid;place-items:center;flex:none;background:var(--ib,#eef4fb);color:var(--ic,var(--b))}
.st .ic svg{width:22px;height:22px;stroke:currentColor;fill:none;stroke-width:2;stroke-linecap:round;stroke-linejoin:round}
.st small{display:block;font-size:12px;font-weight:700;color:var(--mute);text-transform:uppercase;letter-spacing:.5px}
.st b{display:block;font-size:22px;font-weight:800;line-height:1.15;font-variant-numeric:tabular-nums;margin-top:2px}
.st.g{--ib:#e6f6ec;--ic:#12703a}.st.o{--ib:#fdf0e6;--ic:#d9731a}.st.p{--ib:#e8f0fb;--ic:#174679}
/* daftar */
.listhead{display:flex;align-items:center;justify-content:space-between;gap:10px;flex-wrap:wrap;margin:6px 2px 12px}
.listhead h2{margin:0;font-size:18px;letter-spacing:-.3px}
.cards{display:grid;gap:14px}
.sub{background:#fff;border:1px solid var(--l);border-radius:18px;padding:20px 22px;box-shadow:0 6px 18px rgba(11,42,77,.05);position:relative;overflow:hidden;animation:up .35s ease both}
.sub:before{content:"";position:absolute;left:0;top:0;bottom:0;width:5px;background:var(--c,var(--b3))}
.sub:nth-child(2){animation-delay:.05s}.sub:nth-child(3){animation-delay:.1s}.sub:nth-child(n+4){animation-delay:.15s}
@keyframes up{from{opacity:0;transform:translateY(10px)}to{opacity:1;transform:none}}
.shead{display:flex;align-items:flex-start;justify-content:space-between;gap:12px;flex-wrap:wrap}
.shead h3{margin:0;font-size:17px;line-height:1.3;letter-spacing:-.2px;flex:1;min-width:200px}
.badge{display:inline-flex;align-items:center;gap:6px;padding:5px 11px;border-radius:99px;font-size:12.5px;font-weight:700;white-space:nowrap}
.badge:before{content:"";width:7px;height:7px;border-radius:50%;background:currentColor}
.s-blue{background:#e8f0fb;color:#174679}.s-amber{background:#fff6e0;color:#8a4b00}.s-violet{background:#f1ecfb;color:#5b3aa0}.s-green{background:var(--okbg);color:var(--ok)}.s-orange{background:#fdf0e6;color:#9a4a0a}.s-red{background:var(--badbg);color:var(--bad)}
.chips2{display:flex;flex-wrap:wrap;gap:6px;margin:10px 0 0}
.chips2 span{font-size:12.5px;color:var(--mute);background:#f3f6fa;border-radius:8px;padding:3px 9px}
.chips2 .pt{background:#e8f0fb;color:var(--b);font-weight:800}
.chips2 .idc{font-family:ui-monospace,Consolas,monospace;background:#fff;border:1px solid var(--l)}
.sub .alert{margin:16px 0 0}
.prog{display:flex;align-items:flex-start;margin:16px 0 4px}
.pst{flex:1;display:flex;flex-direction:column;align-items:center;position:relative;text-align:center;min-width:0}
.pst:not(:last-child):after{content:"";position:absolute;top:15px;left:calc(50% + 18px);right:calc(-50% + 18px);height:3px;border-radius:3px;background:var(--l)}
.pst.done:not(:last-child):after{background:linear-gradient(90deg,var(--ok),#2fb36a)}
.pst.cur:not(:last-child):after{background:linear-gradient(90deg,var(--b3),var(--l))}
.dot{width:32px;height:32px;border-radius:50%;background:#eef2f7;color:#9aa9bb;display:grid;place-items:center;font-weight:800;font-size:13px;position:relative;z-index:1;border:3px solid #fff;box-shadow:0 0 0 1px var(--l)}
.pst.done .dot{background:var(--ok);color:#fff;box-shadow:none}
.pst.cur .dot{background:var(--b);color:#fff;animation:ring 1.8s ease-out infinite}
@keyframes ring{0%{box-shadow:0 0 0 0 rgba(43,108,176,.4)}100%{box-shadow:0 0 0 12px rgba(43,108,176,0)}}
.dot svg{width:16px;height:16px;stroke:#fff;fill:none;stroke-width:3;stroke-linecap:round;stroke-linejoin:round}
.pst .lb{font-size:12.5px;font-weight:700;color:var(--mute);margin-top:6px;line-height:1.25}
.pst.done .lb,.pst.cur .lb{color:var(--ink)}
.note{margin-top:10px;background:#fdf7e8;color:var(--warn);border-radius:10px;padding:9px 12px;font-size:13.5px}
.aksi{margin-top:12px}
.aksi .btn{background:var(--b);color:#fff;border-color:var(--b);font-size:13.5px;padding:9px 15px}
.aksi .btn:hover{background:var(--b2)}
.empty{background:#fff;border:1px dashed #c3d4ea;border-radius:18px;padding:34px 20px;text-align:center}
.empty .ill{width:64px;height:64px;border-radius:20px;background:#eef4fb;display:grid;place-items:center;margin:0 auto 12px;color:var(--b3)}
.empty .ill svg{width:30px;height:30px;stroke:currentColor;fill:none;stroke-width:1.8;stroke-linecap:round;stroke-linejoin:round}
.empty p{margin:0 0 4px;font-weight:700;color:var(--ink)}
.empty small{color:var(--mute);font-size:13.5px}
.cta{margin-top:22px;background:linear-gradient(135deg,var(--b2),var(--b));border-radius:18px;color:#fff;padding:20px 22px;display:flex;align-items:center;justify-content:space-between;gap:14px;flex-wrap:wrap;box-shadow:0 12px 24px rgba(11,42,77,.2)}
.cta b{display:block;font-size:16px}
.cta small{color:#cfe0f5;font-size:13.5px}
.cta .btn{background:var(--y);color:#10233b;border-color:var(--y);font-weight:800}
.cta .btn:hover{background:#ffd93a}
.foot{text-align:center;color:var(--mute);font-size:12.5px;padding:24px 0 36px}
@media(max-width:620px){
  .top{padding:18px 0 72px}
  .idcard,.lookup{margin-top:-44px}
  .lk-form .btn{width:100%;justify-content:center}
  .lk-head p{font-size:13px}
  .stats{grid-template-columns:1fr 1fr;gap:10px}
  .st:last-child{grid-column:1/-1}
  .st{padding:14px}
  .st .ic{width:38px;height:38px}
  .st b{font-size:19px}
  .sub{padding:18px 16px 16px 20px}
  .pst:not(.cur) .lb{display:none}
  .cta{flex-direction:column;align-items:flex-start}
}
@media(prefers-reduced-motion:reduce){.sub,.pst.cur .dot{animation:none}}

/* ===== KATA SKEM: KUNING + KILAU ===== */
.sk-shine{color:var(--y);background:linear-gradient(110deg,#f6c90e 30%,#ffffff 50%,#f6c90e 70%);background-size:200% auto;-webkit-background-clip:text;background-clip:text;-webkit-text-fill-color:transparent;animation:skShine 3.2s linear infinite}
@keyframes skShine{to{background-position:200% center}}
@media(prefers-reduced-motion:reduce){.sk-shine{animation:none;background:none;-webkit-text-fill-color:currentColor;color:var(--y)}}
</style>
</head>
